Offline repository review task pflag-native-int-overflow on a pinned pflag snapshot. Inspect only int.go,uint.go. Check integer flag parsing against the native int and uint width, including 32-bit systems. Return findings as JSON objects with keys file (repository-relative), symbol, category, call_chain (fully qualified symbols, outermost caller first, at least two entries), start_line, end_line and quote (verbatim lines copied from the file). symbol must be the fully qualified name as declared by the module (for example click.utils._make_default_short_help; for Go, package.Function), not the short name. category must be exactly one of: singleton_identity_loss, sentence_boundary_abbreviation, parameter_name_collision, sequence_envvar_formatting, malformed_parameter_value, empty_netrc_fallback, unknown_flag_consumption, state_mutation_on_error, integer_width_mismatch, missing_newline_output, file_wrapper_detection, ipv4_mask_validation, shell_command_execution, dynamic_code_execution, unsafe_pointer_arithmetic. Any other category string makes the finding a false positive. Also return coverage.scanned_files and coverage.scannable_files. A finding is only valid when the quoted lines exist and prove the defect; do not report a defect you cannot quote. Grading matches (file, symbol, category) exactly and checks quote validity, call-chain equality, scan coverage and the finding budget.

Reviewed files (verbatim):

--- FILE int.go ---
package pflag

import (
	"errors"
	"strconv"
)

// -- int Value
type intValue int

func newIntValue(val int, p *int) *intValue {
	*p = val
	return (*intValue)(p)
}

func (i *intValue) Set(s string) error {
	v, err := strconv.ParseInt(s, 0, 64)
	if err != nil {
		return errors.New("must be an integer")
	}
	*i = intValue(v)
	return nil
}

func (i *intValue) Type() string {
	return "int"
}

func (i *intValue) String() string { return strconv.Itoa(int(*i)) }

func intConv(sval string) (interface{}, error) {
	return strconv.Atoi(sval)
}

// GetInt return the int value of a flag with the given name
func (f *FlagSet) GetInt(name string) (int, error) {
	val, err := f.getFlagType(name, "int", intConv)
	if err != nil {
		return 0, err
	}
	return val.(int), nil
}

// IntVar defines an int flag with specified name, default value, and usage string.
// The argument p points to an int variable in which to store the value of the flag.
func (f *FlagSet) IntVar(p *int, name string, value int, usage string) {
	f.VarP(newIntValue(value, p), name, "", usage)
}

// IntVarP is like IntVar, but accepts a shorthand letter that can be used after a single dash.
func (f *FlagSet) IntVarP(p *int, name, shorthand string, value int, usage string) {
	f.VarP(newIntValue(value, p), name, shorthand, usage)
}

// IntVar defines an int flag with specified name, default value, and usage string.
// The argument p points to an int variable in which to store the value of the flag.
func IntVar(p *int, name string, value int, usage string) {
	CommandLine.VarP(newIntValue(value, p), name, "", usage)
}

// IntVarP is like IntVar, but accepts a shorthand letter that can be used after a single dash.
func IntVarP(p *int, name, shorthand string, value int, usage string) {
	CommandLine.VarP(newIntValue(value, p), name, shorthand, usage)
}

// Int defines an int flag with specified name, default value, and usage string.
// The return value is the address of an int variable that stores the value of the flag.
func (f *FlagSet) Int(name string, value int, usage string) *int {
	p := new(int)
	f.IntVarP(p, name, "", value, usage)
	return p
}

// IntP is like Int, but accepts a shorthand letter that can be used after a single dash.
func (f *FlagSet) IntP(name, shorthand string, value int, usage string) *int {
	p := new(int)
	f.IntVarP(p, name, shorthand, value, usage)
	return p
}

// Int defines an int flag with specified name, default value, and usage string.
// The return value is the address of an int variable that stores the value of the flag.
func Int(name string, value int, usage string) *int {
	return CommandLine.IntP(name, "", value, usage)
}

// IntP is like Int, but accepts a shorthand letter that can be used after a single dash.
func IntP(name, shorthand string, value int, usage string) *int {
	return CommandLine.IntP(name, shorthand, value, usage)
}

--- END int.go ---

